previewCss:
.darma-loader-zipper-merge {
  position: relative;
  width: 26px;
  height: 52px;
}
.darma-loader-zipper-merge::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 11px;
  background: repeating-linear-gradient(var(--loader-color, #6366f1) 0 4px, transparent 4px 8px);
}
.darma-loader-zipper-merge::after {
  content: "";
  position: absolute;
  right: 0;
  top: 0;
  bottom: 0;
  width: 11px;
  background: repeating-linear-gradient(transparent 0 4px, var(--loader-color, #6366f1) 4px 8px);
}
.darma-loader-zipper-merge i {
  position: absolute;
  left: 50%;
  top: 0;
  width: 10px;
  height: 9px;
  margin-left: -5px;
  border-radius: 2px;
  background: #4338ca;
  z-index: 2;
  animation: darma-loader-zipper-merge-zip 1.5s ease-in-out infinite;
}
@keyframes darma-loader-zipper-merge-zip {
  0% { top: 0; }
  50% { top: calc(100% - 9px); }
  100% { top: 0; }
}

